#!/bin/bash
# Q1: refusal paths. Prints the TEST URL forms (not secrets) and measured outcomes only.
set -uo pipefail
source /Volumes/DevMASTER/WEDNESDAY/0_Brain/reference/2026-11-03_gate165-ks915-pr1982/harness/lib.sh
TAG=${1:-q1}
L=$W/runs/$TAG; mkdir -p "$L"

# golden: a completed local .env (generated by the script in its own clone)
G="$(mkclone ${TAG}-golden)" || exit 1
rc=$(run "$G" "$L/golden.log")
echo "golden run rc=$rc"
GOLD="$W/runs/$TAG/golden.env.bin"; cp -p "$G/Blockchain/Dev/.env" "$GOLD"
# a golden with ADMIN_USER_PASSWORD blank, so any non-refused run WOULD write
GB="$W/runs/$TAG/golden_blankadmin.env.bin"
awk 'index($0,"ADMIN_USER_PASSWORD=")==1{print "ADMIN_USER_PASSWORD="; next}{print}' "$GOLD" > "$GB"

M=gate165rmt   # marker present in every remote host below
SHELL_CASES=(
  "postgresql://u:p@db.$M.com:5432/x"
  "postgres://u:p@10.0.0.5/x?a=$M"
  "postgres://u:p@192.168.1.1:5432/x?a=$M"
  "postgres://$M.host:5432/x"
  "postgres://u@$M.host/x"
  "postgres://u:p@$M.host/x?sslmode=require&connect_timeout=5"
  "postgres://u:p@[2001:db8::1]:5432/x?a=$M"
  "postgres://u:p@[::ffff:10.0.0.1]/x?a=$M"
  "postgres://u:p@postgres.$M.com/x"
  "postgres://u:p@localhost.$M.com/x"
  "postgres://u:p@postgres-$M/x"
  "postgres://u:p@DB.$M.COM/x"
  "POSTGRES://U:P@DB.$M.COM/X"
  "postgres://u:p@127.0.0.2/x?a=$M"
  "postgres://u:p@0.0.0.0/x?a=$M"
  "$M.host:5432"
  "host=$M.host dbname=x"
  "\"postgres://u:p@$M.host/x\""
  "'postgres://u:p@$M.host/x'"
  " postgres://u:p@$M.host/x"
  "postgres://u:p@$M.host/x   "
  "postgres://u:p@$M.host/x with spaces"
  "postgres://u:p@ss@$M.host/x"
  "postgres://localhost@$M.host/x"
  "postgres://u:p@localhost/x?host=$M.host"
  "postgres://u:p@localhost/x?HOST=$M.host"
  "postgres://u:p@localhost/x?hostaddr=10.9.9.9&a=$M"
  "postgres://u:p@localhost/x?sslmode=require&host=$M.host"
  "postgres:///x?host=$M.host"
  "postgres://u:p@localhost/x?host=localhost&host=$M.host"
  "postgres://u:p@localhost%2E$M.com/x"
  "postgres://u:p@localhost./x?a=$M"
  "postgres://u:p@[::1/x?a=$M"
  "postgres://u:p@localhost:5432,$M.host:5432/x"
  "postgres://u:p@[::1],$M.host/x"
  "postgres://u:p@[::1]$M.com/x"
  "postgres://u:p@localhost/x?h%6Fst=$M.host"
  "postgres://u:p@localhost/x?host%3D$M.host"
  "postgres://u:p@pgbouncer:6432/x?a=$M"
)
LOCAL_CONTROLS=(
  "postgres://u:p@localhost:6432/x"
  "postgres://u:p@LOCALHOST/x"
  "postgres://u:p@127.0.0.1/x"
  "postgres://u:p@[::1]:5432/x"
  "postgres://u:p@postgres:5432/x"
  "postgres:///x?host=/tmp"
  ""
)

one_shell() {  # one_shell ID URL VARIANT(fresh|present)
  local id="$1" url="$2" var="$3" c t0 t1 o0 o1 rc envf named hostleak created
  c="$(mkclone ${TAG}-s$id-$var)" || return
  envf="$c/Blockchain/Dev/.env"
  if [[ "$var" == present ]]; then cp "$GB" "$envf"; chmod 644 "$envf"; fi
  t0=$(treesum "$c"); o0=$(outsidesum)
  rc=$(run "$c" "$L/s$id-$var.log" "DATABASE_URL=$url")
  t1=$(treesum "$c"); o1=$(outsidesum)
  named=$(grep -q 'DATABASE_URL' "$L/s$id-$var.log" && echo y || echo n)
  hostleak=$(grep -c "$M" "$L/s$id-$var.log")
  created=$([[ -e "$envf" ]] && echo y || echo n)
  printf '%-3s %-7s rc=%-2s tree_same=%s outside_same=%s env_exists=%s names_var=%s marker_in_log=%s | %s\n' \
    "$id" "$var" "$rc" "$([[ $t0 == $t1 ]] && echo y || echo N)" "$([[ $o0 == $o1 ]] && echo y || echo N)" \
    "$created" "$named" "$hostleak" "[$url]"
}

echo "== SHELL DATABASE_URL, expected refusal (rc=3, tree_same=y) =="
i=0
for u in "${SHELL_CASES[@]}"; do i=$((i+1)); one_shell "$i" "$u" fresh; one_shell "$i" "$u" present; done
echo "== SHELL DATABASE_URL, local controls (expected rc=0) =="
j=100
for u in "${LOCAL_CONTROLS[@]}"; do j=$((j+1)); one_shell "$j" "$u" fresh; done

# .env forms: golden_blankadmin with its DATABASE_URL lines replaced by LINES
ENV_CASES=(
  "DATABASE_URL=postgres://u:p@$M.host/x"
  "DATABASE_URL=\"postgres://u:p@$M.host/x\""
  "DATABASE_URL='postgres://u:p@$M.host/x'"
  "DATABASE_URL=postgres://u:p@$M.host/x   # localhost"
  "DATABASE_URL=postgres://u:p@$M.host/x"$'\r'
  "export DATABASE_URL=postgres://u:p@$M.host/x"
  "  DATABASE_URL=postgres://u:p@$M.host/x"
  "DATABASE_URL = postgres://u:p@$M.host/x"
  "DATABASE_URL: postgres://u:p@$M.host/x"
  "DATABASE_URL=postgres://u:p@localhost:6432/x"$'\n'"DATABASE_URL=postgres://u:p@$M.host/x"
  "DATABASE_URL=postgres://u:p@localhost:5432,$M.host:5432/x"
  "DATABASE_URL=postgres://u:p@localhost/x?h%6Fst=$M.host"
)
one_env() {  # one_env ID LINES [SHELLURL]
  local id="$1" lines="$2" shellurl="${3-__unset__}" c envf t0 t1 rc named hostleak
  c="$(mkclone ${TAG}-e$id)" || return
  envf="$c/Blockchain/Dev/.env"
  grep -v '^DATABASE_URL=' "$GB" > "$envf"; printf '%s\n' "$lines" >> "$envf"; chmod 644 "$envf"
  t0=$(treesum "$c")
  if [[ "$shellurl" == __unset__ ]]; then rc=$(run "$c" "$L/e$id.log"); else rc=$(run "$c" "$L/e$id.log" "DATABASE_URL=$shellurl"); fi
  t1=$(treesum "$c")
  named=$(grep -q 'DATABASE_URL' "$L/e$id.log" && echo y || echo n)
  hostleak=$(grep -c "$M" "$L/e$id.log")
  printf '%-3s rc=%-2s tree_same=%s names_var=%s marker_in_log=%s admin_now_set=%s mode=%s | %q%s\n' \
    "$id" "$rc" "$([[ $t0 == $t1 ]] && echo y || echo N)" "$named" "$hostleak" \
    "$([[ -n "$(valof "$envf" ADMIN_USER_PASSWORD)" ]] && echo y || echo n)" "$(mode "$envf")" "$lines" \
    "$([[ "$shellurl" == __unset__ ]] || printf ' + shell[%s]' "$shellurl")"
}
echo "== .env DATABASE_URL forms, expected refusal =="
k=200
for e in "${ENV_CASES[@]}"; do k=$((k+1)); one_env "$k" "$e"; done
echo "== shell vs .env disagreement =="
one_env 251 "DATABASE_URL=postgres://u:p@$M.host/x" "postgres://u:p@localhost/x"
one_env 252 "DATABASE_URL=postgres://u:p@localhost/x" "postgres://u:p@$M.host/x"
one_env 253 "DATABASE_URL=postgres://u:p@$M.host/x" ""

# NODE_ENV
echo "== NODE_ENV =="
one_node() {  # one_node ID WHERE VALUE-or-LINES
  local id="$1" where="$2" v="$3" c envf t0 t1 rc o0 o1
  c="$(mkclone ${TAG}-n$id)" || return
  envf="$c/Blockchain/Dev/.env"
  if [[ "$where" == shell-fresh ]]; then
    t0=$(treesum "$c"); rc=$(run "$c" "$L/n$id.log" "NODE_ENV=$v"); t1=$(treesum "$c")
  elif [[ "$where" == shell-present ]]; then
    cp "$GB" "$envf"; chmod 644 "$envf"
    t0=$(treesum "$c"); rc=$(run "$c" "$L/n$id.log" "NODE_ENV=$v"); t1=$(treesum "$c")
  else
    grep -v '^NODE_ENV=' "$GB" > "$envf"; printf '%s\n' "$v" >> "$envf"; chmod 644 "$envf"
    t0=$(treesum "$c"); rc=$(run "$c" "$L/n$id.log"); t1=$(treesum "$c")
  fi
  printf '%-3s %-13s rc=%-2s tree_same=%s names_var=%s env_exists=%s | %q\n' "$id" "$where" "$rc" \
    "$([[ $t0 == $t1 ]] && echo y || echo N)" "$(grep -q NODE_ENV "$L/n$id.log" && echo y || echo n)" \
    "$([[ -e "$envf" ]] && echo y || echo n)" "$v"
}
one_node 301 shell-fresh production
one_node 302 shell-present production
one_node 303 shell-fresh PRODUCTION
one_node 304 shell-fresh "production "
one_node 305 envfile x "NODE_ENV=production"
one_node 306 envfile x "NODE_ENV=\"production\""
one_node 307 envfile x "NODE_ENV=Production"
one_node 308 envfile x "NODE_ENV=production # live"
one_node 309 envfile x "export NODE_ENV=production"
one_node 310 envfile x "NODE_ENV= production"
one_node 311 envfile x "NODE_ENV=development"$'\n'"NODE_ENV=production"
one_node 312 envfile x "  NODE_ENV=production"
one_node 313 shell-fresh development
one_node 314 envfile x "NODE_ENV=demo"
